// =============================================================================
// tb_cmd_vectors.sv — rec_cmd_parser fed with the exact command strings that tools/recorder.py
// emits (sim/vectors/rec_cmd_vectors.txt, generated by sim/vectors/gen_cmd_vectors.py from the
// cmd_* functions and the unit conversions of the tool).  921600-baud bit timing.
// Passes: LF, CR, CRLF (line by line), then everything as one back-to-back LF stream.
// Negative control: a corrupted expectation / corrupted command text must be flagged.
// =============================================================================
`timescale 1ns/1ps

module tb_cmd_vectors;
  import rec_pkg::*;

  logic clk = 1'b0;
  logic rst = 1'b1;
  always #2.5 clk = ~clk;
  localparam int DIV = 217;

  logic rxd = 1'b1;
  logic [7:0] rx_data;
  logic rx_valid, rx_ferr;
  logic cmd_valid, cmd_ready = 1'b1;
  logic [5:0]  cmd_op;
  logic [3:0]  cmd_sub;
  logic [1:0]  cmd_nargs;
  logic [63:0] cmd_arg0, cmd_arg1, cmd_arg2;
  logic [7:0]  cmd_err;

  uart_rx #(.CLK_HZ(200_000_000), .BAUD(921_600)) u_rx (
    .clk(clk), .rst(rst), .rxd(rxd), .m_data(rx_data), .m_valid(rx_valid), .frame_err(rx_ferr));
  rec_cmd_parser u_dut (
    .clk(clk), .rst(rst), .rx_data(rx_data), .rx_valid(rx_valid), .rx_ferr(rx_ferr),
    .cmd_valid(cmd_valid), .cmd_ready(cmd_ready), .cmd_op(cmd_op), .cmd_sub(cmd_sub),
    .cmd_nargs(cmd_nargs), .cmd_arg0(cmd_arg0), .cmd_arg1(cmd_arg1), .cmd_arg2(cmd_arg2),
    .cmd_err(cmd_err));

  typedef struct {
    logic [5:0] op; logic [3:0] sub; logic [1:0] na; logic [63:0] a0, a1, a2; logic [7:0] err;
  } rec_t;
  rec_t got_q [$];
  rec_t exp_q [$];
  string texts [$];
  int errors = 0, neg_detected = 0;
  bit neg_mode = 1'b0;

  always @(posedge clk) begin
    if (!rst && cmd_valid && cmd_ready)
      got_q.push_back('{cmd_op, cmd_sub, cmd_nargs, cmd_arg0, cmd_arg1, cmd_arg2, cmd_err});
  end

  task automatic wait_clks(input int n);
    repeat (n) @(posedge clk);
    #1;
  endtask
  task automatic send_byte(input logic [7:0] b);
    rxd = 1'b0;                    wait_clks(DIV);
    for (int i = 0; i < 8; i++) begin rxd = b[i]; wait_clks(DIV); end
    rxd = 1'b1;                    wait_clks(DIV);
  endtask
  task automatic send_text(input string s, input int eol);
    for (int i = 0; i < s.len(); i++) send_byte(s.getc(i));
    case (eol)
      0: send_byte(8'h0A);
      1: send_byte(8'h0D);
      2: begin send_byte(8'h0D); send_byte(8'h0A); end
      default: ;
    endcase
  endtask

  task automatic compare(input string tag);
    bit bad;
    int n;
    bad = (got_q.size() != exp_q.size());
    if (bad && !neg_mode) $display("ERROR [%s]: %0d commands, %0d expected", tag, got_q.size(), exp_q.size());
    n = (got_q.size() < exp_q.size()) ? got_q.size() : exp_q.size();
    for (int i = 0; i < n; i++)
      if (got_q[i] !== exp_q[i]) begin
        bad = 1'b1;
        if (!neg_mode)
          $display("ERROR [%s] #%0d: got op=%0d sub=%0d na=%0d a=%h %h %h err=%h  exp op=%0d sub=%0d na=%0d a=%h %h %h err=%h",
                   tag, i, got_q[i].op, got_q[i].sub, got_q[i].na, got_q[i].a0, got_q[i].a1, got_q[i].a2, got_q[i].err,
                   exp_q[i].op, exp_q[i].sub, exp_q[i].na, exp_q[i].a0, exp_q[i].a1, exp_q[i].a2, exp_q[i].err);
      end
    if (bad) begin if (neg_mode) neg_detected++; else errors++; end
    got_q.delete(); exp_q.delete();
  endtask

  int opmap [string];
  rec_t  vexp [$];
  string vtxt [$];

  initial begin
    int fd, n, idx, nv;
    string line, head, text, opname;
    int sub, na;
    logic [63:0] a0, a1, a2;
    rec_t e;
    opmap["OP_PING"] = OP_PING;   opmap["OP_STAT"] = OP_STAT;   opmap["OP_CFGQ"] = OP_CFGQ;
    opmap["OP_RESQ"] = OP_RESQ;   opmap["OP_TEL"] = OP_TEL;     opmap["OP_SMART"] = OP_SMART;
    opmap["OP_SMARTQ"] = OP_SMARTQ; opmap["OP_MODE"] = OP_MODE; opmap["OP_RATE"] = OP_RATE;
    opmap["OP_LEN"] = OP_LEN;     opmap["OP_SID"] = OP_SID;     opmap["OP_DDRSZ"] = OP_DDRSZ;
    opmap["OP_PROF_CLR"] = OP_PROF_CLR; opmap["OP_PROF_ADD"] = OP_PROF_ADD;
    opmap["OP_PROF_SET"] = OP_PROF_SET; opmap["OP_PROF_REP"] = OP_PROF_REP;
    opmap["OP_PROF_END"] = OP_PROF_END; opmap["OP_PROFQ"] = OP_PROFQ; opmap["OP_REC"] = OP_REC;
    opmap["OP_REC_PROF"] = OP_REC_PROF; opmap["OP_STOP"] = OP_STOP; opmap["OP_PFAIL"] = OP_PFAIL;
    opmap["OP_READ_LAST"] = OP_READ_LAST; opmap["OP_READ_N"] = OP_READ_N;
    opmap["OP_READ_END"] = OP_READ_END;   opmap["OP_READ_SID"] = OP_READ_SID;
    opmap["OP_FORMAT"] = OP_FORMAT; opmap["OP_MON"] = OP_MON; opmap["OP_MEMTEST"] = OP_MEMTEST;
    opmap["OP_DTEST"] = OP_DTEST; opmap["OP_DDRQ"] = OP_DDRQ; opmap["OP_ABORT"] = OP_ABORT;

    wait_clks(10);
    rst = 1'b0;
    wait_clks(20);

    fd = $fopen("../../vectors/rec_cmd_vectors.txt", "r");
    if (fd == 0) $fatal(1, "cannot open sim/vectors/rec_cmd_vectors.txt");
    while (!$feof(fd)) begin
      line = "";
      n = $fgets(line, fd);
      if (n == 0 || line.len() < 4 || line.substr(0, 1) == "//") continue;
      idx = 0;
      while (idx < line.len() && line.getc(idx) != "|") idx++;
      if (idx >= line.len()) $fatal(1, "bad vector line: %s", line);
      head = line.substr(0, idx - 1);
      text = line.substr(idx + 2, line.len() - 1);
      while (text.len() > 0 && (text.getc(text.len() - 1) == "\n" || text.getc(text.len() - 1) == 8'h0D))
        text = text.substr(0, text.len() - 2);
      n = $sscanf(head, "%s %d %d %h %h %h", opname, sub, na, a0, a1, a2);
      if (n != 6) $fatal(1, "cannot parse vector header: %s", head);
      if (!opmap.exists(opname)) $fatal(1, "unknown op name %s", opname);
      e.op = 6'(opmap[opname]); e.sub = 4'(sub); e.na = 2'(na);
      e.a0 = a0; e.a1 = a1; e.a2 = a2; e.err = 8'h00;
      vexp.push_back(e); vtxt.push_back(text);
    end
    $fclose(fd);
    nv = vexp.size();
    $display("tb_cmd_vectors: %0d vectors", nv);
    if (nv < 100) $fatal(1, "too few vectors: %0d", nv);

    // ---- line by line with LF, CR, CRLF
    for (int eol = 0; eol < 3; eol++) begin
      for (int i = 0; i < nv; i++) begin
        send_text(vtxt[i], eol);
        wait_clks(60);
        exp_q.push_back(vexp[i]);
        compare($sformatf("eol%0d %s", eol, vtxt[i]));
      end
    end
    // ---- one back-to-back stream
    for (int i = 0; i < nv; i++) begin
      send_text(vtxt[i], 0);
      exp_q.push_back(vexp[i]);
    end
    wait_clks(200);
    compare("stream");

    // ---- negative control: corrupted expectation and corrupted text are caught
    neg_mode = 1'b1;
    send_text(vtxt[0], 0); wait_clks(60);
    e = vexp[0]; e.op = e.op ^ 6'd1;
    exp_q.push_back(e); compare("neg op");
    send_text(vtxt[0], 0); wait_clks(60);
    e = vexp[0]; e.a0 = 64'd1;
    exp_q.push_back(e); compare("neg arg");
    send_text({vtxt[20], "X"}, 0); wait_clks(60);          // corrupted command text
    exp_q.push_back(vexp[20]); compare("neg text");
    neg_mode = 1'b0;
    if (neg_detected != 3) begin errors++; $display("ERROR: negative control %0d of 3", neg_detected); end

    if (errors != 0) $fatal(1, "tb_cmd_vectors: %0d errors", errors);
    $display("TEST PASSED");
    $finish;
  end

  initial begin
    #900ms;
    $fatal(1, "tb_cmd_vectors: timeout");
  end
endmodule
